"""Checks your NOX 1.0 file for stage 3. Do not edit this file.

  python validate.py my-orders.nox
"""
import base64
import re
import subprocess
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent


def check(lines):
    errors, warnings = [], []
    if not lines or lines[0] != "NOX 1.0":
        errors.append("Rule 1 (MUST): the first line must be 'NOX 1.0'.")
    body = [l for l in lines[1:] if not l.startswith("#")]
    if body and body[-1] == "END":
        body = body[:-1]
    else:
        warnings.append("Rule 7 (SHOULD): the last line should be 'END'.")
    seen = set()
    orders = 0
    for n, line in enumerate(body, start=1):
        parts = line.split("|")
        if len(parts) != 4:
            errors.append(f"'{line}': Rule 2 (MUST) and Rule 9 (MUST NOT): an order has exactly 4 parts, and no price.")
            continue
        order_id, item, count, date = parts
        orders += 1
        if not re.fullmatch(r"N\d{4}", order_id):
            errors.append(f"'{line}': Rule 3 (MUST): the ID must look like N0042.")
        elif order_id in seen:
            errors.append(f"'{line}': Rule 10 (MUST): the ID {order_id} is used twice.")
        seen.add(order_id)
        if not count.isdigit() or not 1 <= int(count) <= 20:
            errors.append(f"'{line}': Rule 4 (MUST): COUNT must be a whole number from 1 to 20.")
        if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", date):
            errors.append(f"'{line}': Rule 5 (MUST): DATE must be YYYY-MM-DD.")
        if item != item.lower():
            warnings.append(f"'{line}': Rule 6 (SHOULD): ITEM should be in small letters.")
    return errors, warnings, orders


def copied_lines(lines):
    """Lines copied from sample.nox or from a plan with a mistake (stages 1 and 2 are for reading, not for this tool)."""
    others = set()
    sample = HERE / "sample.nox"
    if sample.is_file():
        others |= {l.strip() for l in sample.read_text(encoding="utf-8").splitlines() if re.match(r"N\d{4}\|", l.strip())}
    mine = {l.strip() for l in lines if re.match(r"N\d{4}\|", l.strip())}
    for name in ("daiki", "kaito", "haruka"):
        plan = HERE / f"plan_{name}.py"
        if not plan.is_file():
            continue
        out = subprocess.run([sys.executable, str(plan)], capture_output=True, text=True).stdout
        orders = {l.strip() for l in out.splitlines() if re.match(r"N\d{4}\|", l.strip())}
        if name == "kaito":
            others |= orders  # lines with prices
        elif orders and mine == orders:
            return sorted(mine)  # the whole output of a plan, as it is
    return [l for l in lines if l.strip() in others]


def main():
    if len(sys.argv) != 2:
        print("Usage: python validate.py my-orders.nox")
        return 2
    if not sys.argv[1].endswith("my-orders.nox"):
        print("このツールがチェックするのは、あなた自身のファイル my-orders.nox だけです（ステージ3）。")
        print("ほかのステージは、自分で SPEC.md を読んで確かめましょう。")
        return 2
    try:
        with open(sys.argv[1], encoding="utf-8") as f:
            lines = [l.rstrip("\n") for l in f if l.strip()]
    except OSError as err:
        sys.exit(f"Cannot read the file: {err}")
    if copied_lines(lines):
        print("sample.nox・案の出力・SPEC.md の例と同じ注文があります。このツールで確かめられるのは、あなたが自分で書いた注文だけです。")
        print("SPEC.md の例を写したときは、注文を足すか変えてください。ステージ1・2は、SPEC.md を読んで自分で確かめましょう。")
        return 1
    errors, warnings, orders = check(lines)
    for w in warnings:
        print("warning:", w)
    for e in errors:
        print("ERROR:", e)
    if errors:
        print(f"Not valid: {len(errors)} MUST rule(s) are broken.")
        return 1
    print(f"Valid NOX 1.0 file with {orders} order(s).", "(Warnings are only SHOULD rules.)" if warnings else "")
    if orders >= 3:
        print("Code word:", base64.b64decode("a2V5c3RvbmU=").decode())
    else:
        print("合言葉を手に入れるには、注文を3つ以上書いてください。")
    return 0


if __name__ == "__main__":
    sys.exit(main())
